var pl;
(function( pl ) {

	// Walk a list term; returns the elements and the term that ends the list.
	var walk = function( list ) {
		var items = [];
		var pointer = list;
		while( pl.type.is_term( pointer ) && pointer.indicator === "./2" ) {
			items.push( pointer.args[0] );
			pointer = pointer.args[1];
		}
		return { items: items, tail: pointer };
	};

	// Build a list term from an array.
	var build = function( items ) {
		var list = new pl.type.Term( "[]", [] );
		for( var i = items.length - 1; i >= 0; i-- )
			list = new pl.type.Term( ".", [items[i], list] );
		return list;
	};

	// True when the term that ends a list closes it.
	var is_closed = function( tail ) {
		return pl.type.is_term( tail ) && tail.indicator === "[]/0";
	};

	// Read a proper list into an array. Throws the matching error and returns null otherwise.
	var read = function( thread, atom, list ) {
		var walked = walk( list );
		if( pl.type.is_variable( walked.tail ) ) {
			thread.throw_error( pl.error.instantiation( atom.indicator ) );
			return null;
		}
		if( !is_closed( walked.tail ) ) {
			thread.throw_error( pl.error.type( "list", list, atom.indicator ) );
			return null;
		}
		return walked.items;
	};

	// Read a proper list of Key-Value pairs into an array of pair terms.
	var read_pairs = function( thread, atom, list ) {
		var items = read( thread, atom, list );
		if( items === null ) return null;
		for( var i = 0; i < items.length; i++ ) {
			var p = items[i];
			if( pl.type.is_variable( p ) ) {
				thread.throw_error( pl.error.instantiation( atom.indicator ) );
				return null;
			}
			if( !pl.type.is_term( p ) || p.indicator !== "-/2" ) {
				thread.throw_error( pl.error.type( "pair", p, atom.indicator ) );
				return null;
			}
		}
		return items;
	};

	// The group collected last, or null when there is none yet.
	var last_of = function( groups ) {
		return groups.length > 0 ? groups[groups.length - 1] : null;
	};

	// Collect consecutive pairs with equal keys into Key-Values groups.
	// The input is not sorted here. Callers sort first when they want one
	// group for each key, so the same key can start more than one group.
	// Keys are compared in standard order and the values keep their order.
	// The groups come back in the order in which their keys first appear.
	var group_by_key = function( pairs ) {
		var groups = [];
		for( var i = 0; i < pairs.length; i++ ) {
			var pair = pairs[i];
			var last = last_of( groups );
			if( last !== null && pl.compare( last.key, pair.args[0] ) === 0 )
				last.values.push( pair.args[1] );
			else
				groups.push( { key: pair.args[0], values: [pair.args[1]] } );
		}
		return groups.map( function( group ) {
			return new pl.type.Term( "-", [group.key, build( group.values )] );
		} );
	};

	// Swap each pair to Value-Key and order the result by the new keys.
	var transpose = function( pairs ) {
		var swapped = pairs.map( function( p ) {
			return new pl.type.Term( "-", [p.args[1], p.args[0]] );
		} );
		return swapped.slice().sort( function( x, y ) {
			return pl.compare( x.args[0], y.args[0] );
		} );
	};

	var predicates = function() {

		// Unify a computed result with the output argument.
		var give = function( thread, point, result, expected ) {
			thread.prepend( [new pl.type.State( point.goal.replace( new pl.type.Term( "=", [result, expected] ) ), point.substitution, point )] );
		};

		// A predicate Pairs, List that keeps one side of every pair.
		var project = function( index ) {
			return function( thread, point, atom ) {
				var pairs = read_pairs( thread, atom, atom.args[0] );
				if( pairs === null ) return;
				if( pairs.length === 0 ) return give( thread, point, new pl.type.Term( "[]", [] ), atom.args[1] );
				give( thread, point, build( pairs.map( function( p ) { return p.args[index]; } ) ), atom.args[1] );
			};
		};

		return {

			// pairs_keys_values/3
			"pairs_keys_values/3": function( thread, point, atom ) {
				var pairs = atom.args[0];
				if( is_closed( walk( pairs ).tail ) ) {
					var items = read_pairs( thread, atom, pairs );
					if( items === null ) return;
					var keys = build( items.map( function( p ) { return p.args[0]; } ) );
					var values = build( items.map( function( p ) { return p.args[1]; } ) );
					var both = new pl.type.Term( ",", [
						new pl.type.Term( "=", [keys, atom.args[1]] ),
						new pl.type.Term( "=", [values, atom.args[2]] )
					] );
					thread.prepend( [new pl.type.State( point.goal.replace( both ), point.substitution, point )] );
				} else {
					var ks = read( thread, atom, atom.args[1] );
					if( ks === null ) return;
					var vs = read( thread, atom, atom.args[2] );
					if( vs === null ) return;
					if( ks.length !== vs.length ) return;
					var count = Math.min( ks.length, vs.length );
					var made = [];
					for( var i = 0; i < count; i++ )
						made.push( new pl.type.Term( "-", [ks[i], vs[i]] ) );
					give( thread, point, build( made ), pairs );
				}
			},

			// pairs_keys/2
			"pairs_keys/2": project( 0 ),

			// pairs_values/2
			"pairs_values/2": project( 1 ),

			// transpose_pairs/2
			"transpose_pairs/2": function( thread, point, atom ) {
				var pairs = read_pairs( thread, atom, atom.args[0] );
				if( pairs === null ) return;
				give( thread, point, build( transpose( pairs ) ), atom.args[1] );
			},

			// group_pairs_by_key/2
			"group_pairs_by_key/2": function( thread, point, atom ) {
				var pairs = read_pairs( thread, atom, atom.args[0] );
				if( pairs === null ) return;
				give( thread, point, build( group_by_key( pairs ) ), atom.args[1] );
			},

			// nth_pair/3
			"nth_pair/3": function( thread, point, atom ) {
				var index = atom.args[0];
				if( pl.type.is_variable( index ) ) {
					thread.throw_error( pl.error.instantiation( atom.indicator ) );
				} else if( !pl.type.is_integer( index ) ) {
					thread.throw_error( pl.error.type( "integer", index, atom.indicator ) );
				} else if( index.value < 0 ) {
					thread.throw_error( pl.error.domain( "not_less_than_zero", index, atom.indicator ) );
				} else {
					var pairs = read_pairs( thread, atom, atom.args[1] );
					if( pairs === null || index.value >= pairs.length ) return;
					give( thread, point, pairs[index.value], atom.args[2] );
				}
			}

		};
	};

	var exports = ["pairs_keys_values/3", "pairs_keys/2", "pairs_values/2", "transpose_pairs/2", "group_pairs_by_key/2", "nth_pair/3"];

	if( typeof module !== 'undefined' ) {
		module.exports = function( p ) {
			pl = p;
			new pl.type.Module( "pairs", predicates(), exports );
		};
	} else {
		new pl.type.Module( "pairs", predicates(), exports );
	}

})( pl );
